"""Regression coverage for the evaluation context of Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('locale', [None, 'en_US', 'fr_FR'])
@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
def test_faker_decider_defaults(locale, chance, expected):
    class TestFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker('boolean', locale=locale, chance_of_getting_true=chance),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert TestFactory()['value'] == expected
    # Evaluating Faker must not consume the declaration's stored defaults.
    assert TestFactory()['value'] == expected


@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
def test_faker_decider_unrolls_defaults(chance, expected):
    class TestFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'boolean',
                chance_of_getting_true=factory.LazyFunction(lambda: chance),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert TestFactory()['value'] == expected


def test_nested_maybe_decider_and_branch_overrides():
    class TestFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
            no_declaration=0,
        )

    assert TestFactory(value__min_value=7, value__max_value=7)['value'] == 7
